def read_positive_quantity(value):
  quantity = int(value)
  if quantity < 1:
    raise ValueError("Quantity must be at least 1")
  return quantity

def prepare_order(order):
  try:
    quantity = read_positive_quantity(order["quantity"])
  except KeyError as error:
    return f"Order read failed: {error}"
  except ValueError as error:
    return f"Quantity failed: {error}"
  total = quantity * order["price"]
  return {"quantity": quantity, "total": total}
